import sys
from datetime import datetime

def parse_time(time_str):
    h, m = map(int, time_str.split(':'))
    return datetime.combine(datetime.min, datetime.time(h, m))

def format_time(duration):
    hours, remainder = divmod(duration.total_seconds() / 3600, 1)
    minutes = remainder // 60
    return f"{int(hours)}:{minutes:02d}"


def main():
    bookings = []
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "book":
            bid, room, day, start_str, end_str = parts[1:]
            start = parse_time(start_str)
            end = parse_time(end_str)
            if end <= start:
                print("INVALID", bid)
                continue
            conflict = None
            for other in bookings:
                other_bid, other_room, other_day, other_start, other_end = other
                if other_room == room and other_day == day and not (end <= other_start or start <= other_end):
                    conflict = other_bid
                    break
            if conflict:
                print(f"REJECT {bid} {conflict}")
            else:
                bookings.append((bid, room, day, start, end))
                print(f"ACCEPT {bid}")
        elif parts[0] == "cancel":
            bookings = [b for b in bookings if b[0] != parts[1]]
            print(f"CANCELLED {parts[1]}")
    rooms = {}
    for bid, room, day, start, end in bookings:
        rooms[room] = rooms.get(room, 0) + 1
    for room in sorted(rooms):
        active = []
        total = timedelta()
        for bid, r, day, start, end in bookings:
            if r == room and day == day and end > start:
                total += end - start
                active.append((bid, start, end))
        count = len(active)
        if count > 0:
            print(f"{room} {count} {format_time(total)}")
